# Revised circACACA/circAcc1 summary tables.
# This R companion script mirrors the table-level analysis used for the figures.
# Figures are generated by 19_circACACA_result_figures.py because Rscript is not
# available in the current Codex shell.

root <- normalizePath(file.path(dirname(sys.frame(1)$ofile), "..", ".."),
                      winslash = "/", mustWork = TRUE)
setwd(root)

out_dir <- "analysis_codex/data/output"
dir.create(out_dir, recursive = TRUE, showWarnings = FALSE)

species <- c("hsa", "mma", "mmu", "mfu", "mpi", "rsi")
labels <- c(
  hsa = "Human (hsa)",
  mma = "Rhesus (mma)",
  mmu = "Mouse (mmu)",
  mfu = "Long-winged bat (mfu)",
  mpi = "Big-footed bat (mpi)",
  rsi = "Horseshoe bat (rsi)"
)

count_atlas_acaca <- function(path) {
  x <- readLines(path, warn = FALSE, encoding = "UTF-8")
  sum(grepl("acaca", x[-1], ignore.case = TRUE))
}

atlas_counts <- data.frame(
  species = c("hsa", "mma", "mmu"),
  species_label = labels[c("hsa", "mma", "mmu")],
  circAtlas_ACACA_count = c(
    count_atlas_acaca("circAtlas_circRNA/human_bed_v3.0.txt"),
    count_atlas_acaca("circAtlas_circRNA/macaca_bed_v3.0.txt"),
    count_atlas_acaca("circAtlas_circRNA/mouse_bed_v3.0.txt")
  ),
  stringsAsFactors = FALSE
)
write.csv(atlas_counts, file.path(out_dir, "circatlas_acaca_counts_from_R.csv"),
          row.names = FALSE)

evidence <- read.csv("New-analysis/acaca_final_evidence.csv",
                     stringsAsFactors = FALSE)
evidence$species_label <- labels[evidence$species]
evidence$integrated_circACACA_evidence <-
  evidence$circ_milk | (!is.na(evidence$circ_atlas) & evidence$circ_atlas)
write.csv(evidence, file.path(out_dir, "circACACA_integrated_evidence_from_R.csv"),
          row.names = FALSE)

presence <- read.csv("New-analysis/gene_presence_matrix.csv",
                     stringsAsFactors = FALSE)
presence$gene_name_upper <- toupper(presence$gene_name)
acaca_presence <- presence[presence$gene_name_upper == "ACACA",
                           c("gene_name", species, "n_species")]
write.csv(acaca_presence,
          file.path(out_dir, "strict_CE_host_gene_ACACA_presence_from_R.csv"),
          row.names = FALSE)

cat("Wrote R companion summary tables to ", out_dir, "\n", sep = "")
